import { useEffect, useState } from "react";

function SearchBox() {
  const [query, setQuery] = useState("");

  useEffect(() => {
    if (!query.trim()) return;

    const id = setTimeout(() => {
      fetch(`/api/search?q=${encodeURIComponent(query)}`);
    }, 300);

    return () => clearTimeout(id);
  }, [query]);

  return (
    <input
      type="search"
      value={query}
      onChange={(e) => setQuery(e.target.value)}
      placeholder="Search..."
    />
  );
}
